"""Operational controls derived from persistent simulation records."""
from .domain import Engine
from .campaign import Campaign
from .business_views import entity_names
from .distress import Distress
from .service_office import DEPARTMENTS
from .property_operations import SYSTEMS,WORK,systems_for,PropertyOperations


def extension_view(world,page,scope):
    from .executives import records as executive_records
    from .campaign_views import field,hidden,choices,form,table,money
    e=Engine(world);c=Campaign(e);names=entity_names(world)
    businesses=[b for b in world.businesses if c.controlled(b.id)]
