    person_names={p.id:p.name for p in world.people}
    employee_names={emp.id:person_names[emp.person_id] for emp in world.employments}
    from .ui_workflows import role_label
    boptions=choices({b.id:b.name for b in businesses});poptions=choices({p.id:p.name for p in props})
    allprops=choices({p.id:p.name for p in world.properties if p.status=='market' or p in props})
    accounts=choices(names);staff=choices({emp.id:person_names[emp.person_id]+' / '+names[emp.employer]+' / '+next(p.role for p in world.positions if p.id==emp.position_id) for emp in employees})
    view=dict(title=page.replace('_',' ').title(),intro='',forms=[],tables=[],metrics=[],notes=[],links=[],page=page)
    if page=='operations_center':
        view.update(title='Operations and recovery',intro='Cash obligations, operational health and improvements at your current scale. A headquarters is optional.')
        view['tables'].append(table('Financial condition',['Entity','Phase','Overdue','Oldest overdue'],[(name,world.systems.get('distress',{}).get(entity,{}).get('phase','healthy'),money(world.systems.get('distress',{}).get(entity,{}).get('overdue',0)),str(world.systems.get('distress',{}).get(entity,{}).get('age',0))+' days') for entity,name in names.items()]))
        view['tables'].append(table('Dated obligations in selected account',['Account','Source','Due','Remaining'],[(r['account'],r['source'],r['due'],money(r['remaining'])) for r in Distress(e).obligations(scope)]))
        view['tables'].append(table('Operating asset liquidations',['Business','Status','Closing date','Share of book value','Cash received'],[(names.get(p['entity'],p['entity']),p['status'],p['due'],str(p['percent'])+'%',money(p.get('proceeds',0))) for p in world.systems.get('asset_liquidations',[])]))
        view['forms'].append(form('liquidate_assets','Market a closed operation’s remaining assets','Equipment, inventory and customer-loan assets can sell at a loss after 14 days; a buyer can withdraw. Marketing costs $250. Property sales remain in the Property workbench.',[field('entity','Closed operation','','select',choices({b.id:b.name for b in businesses if b.status=='closed'}))]))
        view['forms']+=[form('settle_obligations','Pay recorded obligations','Available cash pays earned wages, suppliers and taxes. Loans and rent retain their counterparties.',[field('entity','Paying account',scope,'select',accounts)]),
            form('negotiate_terms','Request supplier terms','A supplier can accept one 21-day extension or refuse. Debt is never erased.',[field('entity','Borrower',scope,'select',accounts)]),
            form('close_operation','Close operations','Ends employment and accrues severance. Assets, debts and identities remain; owners do not automatically absorb debts.',[field('entity','Business','','select',boptions)]),
            form('local_improvement','Improve one location','Build equipment capacity, quality, automation or customer relationships, or service equipment. No unrelated industry is required.',[field('business_id','Business','','select',boptions),field('kind','Improvement','maintenance','select',choices({k:k.title() for k in ('maintenance','equipment','quality','loyalty','automation')}))])]
        view['forms'].append(form('start_location','Open another location within one company','Same-industry location with separate operating books, shared legal obligations and a consolidated company income-tax assessment. Opening requires funded setup, equipment, working capital and qualified staff.',[field('entity','Existing company','','select',boptions),field('name','New location name'),field('region','County','Rutland County','select',choices({r['id']:r['id'] for r in world.systems['regions']}))]))
