            fields=[hidden('business_id',b.id)]
            fields += [field(k,'Prefer home-office and owned property specialists' if k=='prefer_internal_property' else k.replace('_',' ').title(),policy.get(k,False),'checkbox') for k in FLAGS]
            fields += [field('location_limit','Maximum same-industry locations',policy.get('location_limit',1),'number',minimum=1,maximum=20),field('loan_limit_dollars','Maximum working-capital proposal ($)',policy.get('loan_limit',1000000)/100,'number',minimum=0),field('flip_limit','Concurrent flips',policy.get('flip_limit',1),'number',minimum=0,maximum=10),field('flip_capital_dollars','Total committed flip capital ($)',policy.get('flip_capital',10000000)/100,'number',minimum=0),field('flip_downside_dollars','Maximum planned downside ($)',policy.get('flip_downside',0)/100,'number',minimum=0),field('service_roles','Services to renew',policy.get('service_roles',[]),'multiselect',choices({k:v[0] for k,v in DEPARTMENTS.items()}))]
            view['forms'].append(form('autonomy_policy',b.name+' — delegated objectives','Routine property work prefers qualified home-office staff, then other owned providers, subject to workload, licenses and county coverage. Clear the internal-specialist preference to use outside providers. Agent preparation consumes staff time before closing fees fall. Financing, property purchases and sales require permission; limits count future commitments.',fields))
