        view['tables'].append(table('Accounting work products',['Account','Prepared','Period starts','Revenue','Expenses','Profit','Cash'],[(names.get(r['business_id'],r['business_id']),r['date'],r['from_date'],money(r['revenue']),money(r['expenses']),money(r['profit']),money(r['cash'])) for r in world.systems.get('management_reports',[])[-30:]]))
        view['tables'].append(table('Legal results',['Task','Original offer','Documented concession','Cash recovered','Unresolved / outcome'],[(t['id'],money(t['original_offer'] or 0),money(t['improvement']),money(t['recovered']),t['outcome']) for t in world.systems.get('service_tasks',[]) if t['department']=='legal']))
        view['tables'].append(table('Employee directory for assignments',['Employment ID','Employee','Employer','Role'],[(emp.id,person_names[emp.person_id],names[emp.employer],next(p.role for p in world.positions if p.id==emp.position_id)) for emp in employees]))
        view['forms'].append(form('department_configure','Configure a staffed department','Tools cost $500 per level. Select employees by name, or leave blank for all qualified staff in the role. Creating a department provides no benefit by itself.',[field('provider','Employing business','','select',boptions),field('department','Department','hr','select',choices({k:k.upper() if k in ('hr','it') else k.title() for k in DEPARTMENTS})),field('staff','Assigned staff (none: all qualified role staff)',[],'multiselect',staff),field('tools','Tool level',1,'number',minimum=1,maximum=3),field('regions','Covered counties, comma separated','Rutland County'),field('industries','Industry expertise, comma separated','retail')]))
        targets={b.id:b.name for b in world.businesses if b.status=='market'}
