            rows.append((p.name,income.get('since','Tracking begins next day'),money(income.get('collected',0)),money(operating),money(cash),str(occupied)+' / '+str(max(1,len(p.spaces))),money(sum(l['arrears'] for l in leases)),money(p.value)))
