        view['tables'].append(table('Systems and inspections',['Property','Category','Condition','Inspected systems / uncertainty'],[(p.name,p.category,p.condition,str(world.systems.get('inspections',{}).get(p.id,{}).get('readings','Not inspected'))+' +/-5' if p.id in world.systems.get('inspections',{}) else 'Not inspected') for p in props]))
